cd /Users/logan/IDAHO-VAULT
python3 - <<'PY'
import subprocess, os, re, collections
paths=[l.rstrip('\n') for l in open('/tmp/deleted.txt') if l.strip()]
dup=re.compile(r'^(.*?) \((\d+)\)(\.[^.]*)?$')
def isdup(p):
    b=os.path.basename(p); d=os.path.dirname(p); m=dup.match(b)
    return bool(m) and os.path.exists(os.path.join(d,m.group(1)+(m.group(3) or '')))

# index every file on disk by its git blob hash is too slow; instead index by stem
bystem=collections.defaultdict(list)
for f in os.listdir('.'):
    m=re.match(r'^(.*?)__src_.*?(\.[^.]*)?$', f)
    if m: bystem[(m.group(1), (m.group(2) or '').lower())].append(f)

res=collections.Counter(); unmatched=[]
for p in paths:
    if isdup(p): res['dedup (original on disk)']+=1; continue
    if p.startswith(('.claude/','.codex/','.dropbox')) or '(WIN)' in p or p.startswith('pet-runs/'):
        res['agent/sync artifact']+=1; continue
    stem,ext=os.path.splitext(os.path.basename(p))
    cand=bystem.get((stem, ext.lower()), [])
    if not cand: res['NO renamed counterpart']+=1; unmatched.append(p); continue
    head=subprocess.run(['git','rev-parse',f'HEAD:{p}'],capture_output=True,text=True).stdout.strip()
    disk=subprocess.run(['git','hash-object',cand[0]],capture_output=True,text=True).stdout.strip()
    res['renamed, content IDENTICAL'if head==disk else 'renamed but CONTENT DIFFERS']+=1
    if head!=disk: unmatched.append(p)
print(f"  total deletions: {len(paths)}\n")
for k,v in res.most_common(): print(f"    {v:4}  {k}")
print(f"\n  needing explanation ({len(unmatched)}):")
for p in unmatched[:20]: print(f"    {p}")
if len(unmatched)>20: print(f"    ... and {len(unmatched)-20} more")
PY

cd /Users/logan/IDAHO-VAULT
timeout() { :; }
git ls-tree -r --long origin/main -- 'Zoom' 2>/dev/null | awk '{printf "  %12s  %s\n", $4, substr($0, index($0,$5))}' | head -20

cd /Users/logan/IDAHO-VAULT
git lfs ls-files -s 2>/dev/null | awk '{
  # size is like "(11.28 GB)" at end
  n=match($0, /\(([0-9.]+) (GB|MB|KB|B)\)/, m)
}' 2>/dev/null || true
git lfs ls-files -s 2>/dev/null | grep -E '\([0-9.]+ GB\)' | awk '{
  match($0,/\(([0-9.]+) GB\)/,m); if (m[1]+0 > 2.0) print
}' 2>/dev/null | head -20 | sed 's/^/  /'
echo "  --- fallback if awk match unsupported ---"
git lfs ls-files -s 2>/dev/null | grep -E '\([0-9.]+ GB\)' | while IFS= read -r l; do
  g=$(echo "$l" | sed -n 's/.*(\([0-9.]*\) GB).*/\1/p')
  awk -v g="$g" 'BEGIN{exit !(g+0>2.0)}' && echo "  $l"
done | head -20

